insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Cobra de bruços', 'Deite de bruços com os braços ao lado do corpo e a testa apoiada. Aproxime as escápulas, gire as palmas para baixo e eleve o peito e os braços alguns centímetros, com o olhar para o chão. Segure 3 segundos e desça devagar. Cuidado: não jogue a cabeça para trás: o pescoço acompanha a coluna.', 3, '8 (segure 3 s)', array['fotos-exercicios/cobra-de-brucos-1.webp','fotos-exercicios/cobra-de-brucos-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Cobra de bruços');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'W deitado de bruços', 'Deite de bruços com a testa apoiada e os cotovelos dobrados na altura dos ombros, formando um W com os braços. Aproxime as escápulas e eleve os braços do apoio, com o olhar para baixo. Segure 2 a 3 segundos e desça devagar. Cuidado: movimento pequeno, sem arquear a lombar.', 2, '10', array['fotos-exercicios/w-de-brucos-1.webp','fotos-exercicios/w-de-brucos-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'W deitado de bruços');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Passar a agulha', 'Em quatro apoios, mãos abaixo dos ombros e joelhos abaixo do quadril. Abra um braço para o teto acompanhando com o olhar e depois passe esse braço por baixo do corpo, entre a mão e o joelho de apoio, girando a parte alta das costas. Volte devagar. Cuidado: o quadril fica parado: o giro vem do meio das costas.', 2, '8 por lado', array['fotos-exercicios/passar-a-agulha-1.webp','fotos-exercicios/passar-a-agulha-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Passar a agulha');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Postura da criança', 'Em quatro apoios, leve o quadril em direção aos calcanhares e estique os braços à frente, apoiando a testa. Respire devagar, deixando as costas soltarem a cada vez que soltar o ar. Cuidado: se incomodar os joelhos, coloque um travesseiro entre o quadril e os calcanhares.', 2, '30 s', array['fotos-exercicios/postura-da-crianca-1.webp','fotos-exercicios/postura-da-crianca-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Postura da criança');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Rotação torácica em quatro apoios', 'Em quatro apoios, coloque uma mão atrás da cabeça. Leve o cotovelo em direção ao braço de apoio e depois gire abrindo o cotovelo para o teto, acompanhando com o olhar. Volte devagar. Cuidado: quadril parado e movimento sem dor.', 2, '8 por lado', array['fotos-exercicios/rotacao-toracica-quatro-apoios-1.webp','fotos-exercicios/rotacao-toracica-quatro-apoios-2.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Rotação torácica em quatro apoios');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Rotação lombar deitado', 'Deite de barriga para cima com os joelhos dobrados e juntos, pés apoiados. Deixe os joelhos caírem devagar para um lado, só até onde for confortável, e volte ao centro; depois vá para o outro lado. Os ombros ficam apoiados. Cuidado: movimento suave, sem forçar a amplitude.', 2, '8 por lado', array['fotos-exercicios/rotacao-lombar-deitado-1.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Rotação lombar deitado');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Joelho ao peito parcial (dias de crise)', 'Deitado de barriga para cima, com a outra perna apoiada, traga um joelho em direção ao peito só até sentir o primeiro alongamento. Segure alguns segundos e volte devagar. Cuidado: nos dias de crise, pouca amplitude já é suficiente.', 2, '5 por lado', array['fotos-exercicios/joelho-ao-peito-parcial-1.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Joelho ao peito parcial (dias de crise)');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Báscula pélvica curta (dias de crise)', 'Deitado com os joelhos dobrados, encoste levemente a lombar no apoio girando a pelve para trás e depois solte. Movimento bem pequeno, no ritmo da respiração. Cuidado: sem forçar. Se a dor aumentar, pare.', 2, '10', array['fotos-exercicios/bascula-pelvica-curta-1.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Báscula pélvica curta (dias de crise)');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Caminhada curta (dias de crise)', 'Caminhe dentro de casa em passos curtos e no seu ritmo, com os braços soltos e a respiração tranquila. Repita algumas vezes ao dia. Cuidado: prefira várias caminhadas curtas a uma longa.', 1, '5 min', array['fotos-exercicios/caminhada-curta-1.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Caminhada curta (dias de crise)');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Descanso deitado de lado (dias de crise)', 'Deite de lado com os joelhos levemente dobrados, um travesseiro entre os joelhos e outro sob a cabeça. Respire devagar e solte o corpo. Cuidado: posição de alívio: use quando a dor apertar.', 1, '5 min', array['fotos-exercicios/descanso-de-lado-1.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Descanso deitado de lado (dias de crise)');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Respiração sentado (pausa no trabalho)', 'Sentado, pés apoiados no chão, uma mão no peito e outra na barriga. Puxe o ar pelo nariz deixando a barriga subir mais que o peito e solte o ar devagar pela boca. Cuidado: use nas pausas do trabalho.', 1, '5 respirações', array['fotos-exercicios/respiracao-sentado-1.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Respiração sentado (pausa no trabalho)');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Rotação de tronco sentado (pausa no trabalho)', 'Sentado, com o quadril parado na cadeira, gire o tronco devagar para um lado, com o olhar acompanhando, e volte. Depois gire para o outro lado. Cuidado: gire só até onde for confortável.', 1, '5 por lado', array['fotos-exercicios/rotacao-tronco-sentado-1.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Rotação de tronco sentado (pausa no trabalho)');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Inclinação lateral em pé (pausa no trabalho)', 'Em pé, pés na largura do quadril e uma mão na cintura. Leve o outro braço por cima da cabeça e incline o tronco para o lado, sem girar. Volte e troque o lado. Cuidado: incline sem girar o tronco e sem prender a respiração.', 1, '5 por lado', array['fotos-exercicios/inclinacao-lateral-em-pe-1.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Inclinação lateral em pé (pausa no trabalho)');
insert into public.exercicios (nome, instrucoes, series_padrao, reps_padrao, fotos, ativo) select 'Sentar e levantar da cadeira', 'Sente na ponta da cadeira com os pés apoiados no chão. Leve o tronco à frente e fique em pé empurrando o chão com os pés. Sente devagar, controlando a descida. Cuidado: use os braços para ajudar, se precisar.', 2, '10', array['fotos-exercicios/sentar-e-levantar-1.webp']::text[], true where not exists (select 1 from public.exercicios where nome = 'Sentar e levantar da cadeira');
